/** Florian 16 Oct 2026: "What a decision costs" (v1.5 page, lost with v1.6.0) returns on the live boards: the cost unit,
 *  the price rules this board applies, and every estimated row's own documented basis (shortened; full text in the cell tooltip). */
const ESTIMATE_KINDS = new Set(['estimate', 'estimated', 'mixed']);
const shortBasis = (basis: string) => {
  const plain = basis.replace(/\s*\((?:https?:[^)]*|[^)]*#\d{4,}[^)]*)\)/g, '').replace(/\s+/g, ' ').trim();
  const first = plain.match(/^.{40,}?[.;](?=\s|$)/)?.[0] ?? plain;
  return first.length > 220 ? `${first.slice(0, 217).trimEnd()}…` : first.replace(/[;,]$/, '.');
};
function DecisionCosts({ scope, rows }: { scope: JevScope; rows: Array<{ key: string; display: string; cost?: { kind?: string | null; basis?: string | null; usd_per_1000?: number | null } | null }> }) {
  const estimated = rows.filter((r) => ESTIMATE_KINDS.has(r.cost?.kind ?? '') && r.cost?.basis);
  const tariffs = rows.filter((r) => r.cost?.kind === 'tariff').length;
  const unpriced = rows.filter((r) => r.cost?.kind === 'unpriced').length;
  return <section id="jev-costs-section" className="mt-10 max-w-4xl scroll-mt-6 text-sm" data-bh-jev-costs>
    <h2 className="mb-3 text-2xl font-bold">What a decision costs</h2>
    <p className="bh-panel mb-3 p-3 text-[15px]" data-bh-jev15-cost-unit-panel>
      <b>Every price here is US dollars per 1,000 decisions, not per 1,000 tokens.</b>{' '}
      One decision is a whole typed request (state, rubric and options), not a single token.
    </p>
    <JevCostsDisclosure>
      <p className="bh-muted mt-2">Rows with a public tariff (per token or per request) are priced at that tariff times the tokens they used; {tariffs} {tariffs === 1 ? 'row on this board carries' : 'rows on this board carry'} one.{scope !== 'api' && <> Open-weights rows have no tariff of their own: they carry the market reference price of their base model (the list price of the same weights at a large inference provider) times their tokens, marked &ldquo;est.&rdquo;.</>} Most rows keep their documented v1.5 cost per 1,000 decisions; each row&apos;s basis below and in its cost cell says how it was priced. We do not use per-minute GPU rental or our own CPU time{scope === 'open' ? '; the What-If calculator above shows that view separately' : '; the GPU cost calculator on the main board shows that view separately'}.{unpriced > 0 && <> {unpriced} {unpriced === 1 ? 'row has' : 'rows have'} no eligible price and {unpriced === 1 ? 'is' : 'are'} listed as unpriced.</>}</p>
      <p className="bh-muted mt-2" data-bh-jev-price-rules><b className="text-gray-200">Price rules.</b> Only public, bookable list prices that have been in effect for at least 30 days count; a manufacturer&apos;s standard, non-promotional launch list price counts from day one, and promotions, subsidies, credits and free tiers never do. A self-hosted open-weights row is never priced below its base model&apos;s market reference price; API offerings are ranked at their own list price. A system without any eligible price is listed as unpriced. A later price change triggers a re-score with a visible note on the row.</p>
      {scope === 'all' && <p className="bh-muted mt-2" data-bh-jev-api-price-rule><b className="text-gray-200">API models with a known base model.</b> On this board they also show a striped second bar: the score and rank they would have at the base-model reference price.</p>}
      {estimated.length > 0 && <ul className="mt-3 space-y-1.5" data-bh-jev-cost-rows>
        {estimated.map((r) => <li key={r.key} data-bh-jev-cost-row={r.key}><b>{short(r.display)}</b>: <span className="whitespace-nowrap">~{r.cost?.usd_per_1000 == null ? 'n/a' : `$${r.cost.usd_per_1000.toFixed(4)}`} <span className="bh-thin-tag">est.</span></span> per 1,000 decisions. <span className="bh-muted">{shortBasis(r.cost?.basis ?? '')}</span></li>)}
      </ul>}
    </JevCostsDisclosure>
  </section>;
}

// CR-320: a low-n cell's shade is dimmed in CSS ([data-bh-heat-low-n]); opacity here also faded the number below 4.5:1.
const completedLanguageN = (cell: { n: number; coverage_n?: number }) => cell.coverage_n ?? cell.n;

function heat(competence: number): CSSProperties {
  const t = Math.max(0, Math.min(1, competence / 100));
  // Site heat scale (.bh-heat in globals.css reads --h in 0..1).
  return { ['--h' as string]: t.toFixed(3) } as CSSProperties;
}

function LanguageView({ a, categories, hiddenApi, scope, carry }: { carry: JevV16Carry; scope: JevScope; a: JevV16ReleaseArtifact; categories: JevV16Categories; hiddenApi: ReadonlySet<string> }) {
  const systems = ['v1.6.3', 'v1.6.4'].includes(a.revision) ? freshJevbenchCategoryRows(a.systems.filter(s => categories.systems[s.key])) : categories.language_cells ? jevLanguageRows(languageRoster(a.systems, a.not_measured, carry.rows, categories.systems, jevScopeClassifier(a.systems, carry.rows, a.not_measured), scope), scope) : a.systems.filter((s) => listedRow(s) && categories.systems[s.key]).sort(byBoard);
  const belowRanking = (s: { listing?: string } | undefined) => s?.listing === 'wrapper' || s?.listing === 'subsidized';
  // v1.8.10 fast path: the live language table shows every published cell with at least BREAKDOWN_MIN_SHOWN_N completed responses (low n marked †).
  const minN = (categories as typeof categories & { display_min_n?: number }).display_min_n ?? (categories.language_cells ? Math.min(categories.language_cells.min_n, BREAKDOWN_MIN_SHOWN_N) : categories.min_n);
  const allLangs = categories.languages.filter((l) => l.key !== 'en').sort((x, y) => y.n - x.n);
  const en = categories.languages.find((l) => l.key === 'en');
  // CR-290 (Florian 5 Oct 2026): a language column in which no system reaches the reporting minimum was all dashes.
  // Those columns are not drawn; their languages and item counts are listed in the caption instead. Display only.
  const shown = (l: { key: string }) => systems.some((s) => (categories.systems[s.key]?.languages?.[l.key]?.n ?? 0) >= minN);
  const langs = allLangs.filter(shown);
  const hidden = allLangs.filter((l) => !shown(l));
  // Florian 10 Oct 2026: the mixed-language group is the first column, then English, then the single languages by item count.
  const mixed = langs.find((l) => l.key === 'mixed');
  const columns = [...(mixed ? [mixed] : []), ...(en ? [en] : []), ...langs.filter((l) => l.key !== 'mixed')];
  const languageRows = systems.map((s, i) => {
        const remarks = [
          categories.supplement && spokeReason(s.key),
          'language_listing_note' in s && s.language_listing_note,
          exposureNote(s.key),
          languageNoteOf(categories, s.key),
        ].filter(Boolean).join('\n');
        const rowTitle = `${s.display} · ${laneTag(s)}\nMeasured item pools: ${coverageOf(categories, s.key)}${remarks ? `\n${remarks}` : ''}`;
        const node = <Fragment key={s.key}>
        {(['v1.6.3', 'v1.6.4'].includes(a.revision) ? belowRanking(s) && !belowRanking(systems[i - 1]) : (s.listing as string) === 'wrapper' && (systems[i - 1]?.listing as string) !== 'wrapper') && <tr data-bh-jev16-language-group={s.key} {...apiRowProps(s.key, hiddenApi)}><th colSpan={1 + (en ? 1 : 0) + langs.length} className="p-2 pt-4" scope="colgroup" title="These systems are listed separately and never ranked.">{['v1.6.3', 'v1.6.4'].includes(a.revision) ? 'Wrappers and subsidized systems (listed, never ranked)' : 'Wrappers (listed, never ranked)'}</th></tr>}
        <tr data-bh-jev16-language-row={s.key} className="border-t border-line" {...apiRowProps(s.key, hiddenApi)}>
        <th scope="row" className="sticky left-0 z-10 bg-[rgb(var(--panel))] p-1.5 font-normal" title={rowTitle}>
          <span className="block w-56 truncate">{nameLabel(s.display, systems)}</span>
          <span className="bh-muted block w-56 truncate">{laneTag(s)} · <span data-bh-jev16-cell-coverage={coverageOf(categories, s.key)}>{coverageOf(categories, s.key)}</span>{remarks && <span aria-hidden="true"> · ⓘ</span>}</span>
          {categories.supplement && spokeReason(s.key) && <span className="sr-only" data-bh-radar-spoke-exception={s.key}>{spokeReason(s.key)}</span>}
          {'language_listing_note' in s && s.language_listing_note && <span className="sr-only" data-bh-language-listing={s.key}>{s.language_listing_note}</span>}
          {exposureNote(s.key) && <span className="sr-only" data-bh-l3-exposure-note={s.key}>{exposureNote(s.key)}</span>}
          {languageNoteOf(categories, s.key) && <span className="sr-only" data-bh-language-coverage-note={s.key}>{languageNoteOf(categories, s.key)}</span>}
        </th>
        {columns.map((l) => {
          const c = categories.systems[s.key]?.languages?.[l.key];
          if (!c || completedLanguageN(c) < minN) {
            const status = c ? `${completedLanguageN(c)} completed responses; below the ${minN}-item reporting minimum` : `Not plotted; fewer than ${minN} answered items`;
            return <td key={l.key} className="p-1.5 text-center bh-muted" title={`${l.label}: ${status}\n${rowTitle}`} aria-label={`${l.label}: ${status}\n${rowTitle}`} data-bh-jev16-language-suppressed>{!c ? '—' : '·'}</td>;
          }
          const lowN = completedLanguageN(c) < 30;
          return <td key={l.key} className="bh-heat p-1.5 text-center" style={heat(c.competence)} data-bh-heat-low-n={lowN ? '' : undefined} title={`${l.label}: ${c.competence.toFixed(1)} over ${c.n} scored observations; ${completedLanguageN(c)} completed responses${lowN ? ' (low n)' : ''}\n${rowTitle}`}>{c.competence.toFixed(0)}{lowN && <sup className="ml-0.5 text-[10px]" aria-label="low n: fewer than 30 answered items">†</sup>}</td>;
        })}
      </tr></Fragment>;
        const values = Object.fromEntries(columns.map((l) => { const c = categories.systems[s.key]?.languages?.[l.key]; return [l.key, c && completedLanguageN(c) >= minN ? c.competence : null]; }));
        return { key: s.key, name: s.display, group: laneTag(s) === 'self-hosted' ? 'open' as const : 'api' as const, index: i, values, node };
      });
  const languageColumns = columns.map((l) => ({ key: l.key, label: l.label, n: l.n, lowN: l.n < 30, title: `${l.label}: ${l.n} items (${l.open} public, ${l.sealed} sealed)` }));
  return <section className="mt-10" aria-labelledby="jev16-languages" data-bh-jev16-language-view>
    <h2 id="jev16-languages" className="text-2xl font-bold">Languages</h2>
    <p className="bh-muted mt-1 max-w-4xl text-sm">Raw chance-corrected competence per item language (0 = chance, 100 = perfect; can be negative), from each system&apos;s own measured items:
      {' '}{categories.language_cells ? languagePoolNote(categories.language_cells) : `Self-hosted rows use S ${a.v16.counts.S} + P ${a.v16.counts.P}; API rows use their measured sealed subset plus P. Sage (A3) language cells and A2/A3 topic/use-case cells cover public P300 only. Raw and outside the Composite.`} {((categories as typeof categories & { display_min_n?: number }).display_min_n ?? 0) >= 30 ? 'Breakdown values are shown for cells with at least 30 scored items; more items are being added.' : <>Cells under {minN} completed supported responses are left empty; recorded input refusals count toward coverage. A dagger (†) marks fewer than 30 completed responses.</>} Competence retains all supported scored observations, including failures and refusals.
      {!categories.language_cells && !categories.supplement && ` Per-language coverage grows with the expanded uc1.1 multilingual pool, a candidate for a later release that is not part of ${a.revision}.`}
