  const meta = new Map<string, unknown>(carry.rows.map((r) => [r.key, r]));
  const { prelim, pending } = jevApiPreliminaryRows(apiPublicSet, meta);
  return [...prelim, ...pending].filter((r) => !measured.has(r.key));
