  const board = await assembleJevBoard({ release: { artifact: release_, categories: releaseCategories, carry: releaseCarry }, previous, live, apiA4 });
  const merged = board.merged as typeof release_;
  const categories = board.categories as typeof releaseCategories;
  const published = board.published as typeof release_;
  const publishedCarry = board.publishedCarry as typeof releaseCarry;
  const addenda = board.addenda;
  // v1.7.12: the method footer also hashes the live cell supplement.
  const cellSupplementSha256 = board.live ? createHash('sha256').update(await readFile(path.join(process.cwd(), JEVBENCH_S_CATEGORY_CELLS_ARTIFACT))).digest('hex') : undefined;
  const revision = published.revision as 'v1.6.0' | 'v1.6.1';
  const previousRelease = revision === 'v1.6.1' ? 'v1.6.0' : 'v1.5.7';
  const previousHref = revision === 'v1.6.1' ? '/jev-models/v1.6.0' : '/jev-models/v1.5.7';
  const allApiFull = release_.systems.filter((system) => system.v16.lane === 'api').every((system) => system.v16.full_set_api === true);
  const a4Count = !board.live ? 0 : merged.systems.filter((s) => (s as { a4?: unknown }).a4).length;
  const publishedKeys = new Set([...published.systems, ...published.not_measured, ...publishedCarry.rows].map((row) => row.key));
  const missingPrevious = [...previous.artifact.systems, ...previous.artifact.not_measured]
    .filter((row) => !isJevbenchV16ExcludedKey(row.key, revision) && !publishedKeys.has(row.key));
  if (missingPrevious.length) throw new Error(`JevBench ${revision} catalogue omits public prior rows: ${missingPrevious.map((row) => row.key).join(', ')}`);
  const isApi = jevScopeClassifier(published.systems, publishedCarry.rows, previous.artifact.systems, previous.artifact.not_measured);
  const scoped = live && scope === 'all' ? jevLiveAllArtifact(published, isApi) as ReturnType<typeof jevbenchScopeArtifact<typeof published>> : jevbenchScopeArtifact(published, scope, isApi);
  // v1.7.12: the method footer also hashes the live cell supplement.
  // CR-327: no runner-local adapter paths in the client payload (Google followed them as links).
  const artifact = withPublicAdapterIds(cellSupplementSha256 ? { ...scoped, cellSupplementSha256 } as typeof scoped : scoped);
  const carry = jevbenchScopeCarry(publishedCarry, scope === 'api' ? 'api' : 'all', isApi);
  const apiKeys = scope === 'open' ? jevApiOfferingKeys([...published.systems, ...published.not_measured, ...publishedCarry.rows], isApi) : [];
  const carryCount = carry.rows.filter((row) => !apiKeys.includes(row.key)).length;
  const apiItems = allApiFull ? artifact.v16.counts.selfhosted_input.toLocaleString('en-US') : artifact.v16.counts.api_input;
  const sharePath = versionPath ?? (scope === 'api' ? '/jev-models/api' : live ? '/jev-models' : `/jev-models/${revision}`);
  const rankedSelfHosted = artifact.systems.filter((s) => s.ranked && s.v16.lane !== 'api').length;
  const rankedApi = artifact.systems.filter((s) => s.ranked && s.v16.lane === 'api').length;
  // v1.7.1: catalogue-only API rows (wrappers, partial runs, not yet measured) for the roster on /jev-models/api.
  const apiListed = scope === 'api' ? jevApiRoster(artifact, carry.rows, previous.artifact.systems, previous.artifact.revision as string).listed : [];

  const cohortRows = artifact.systems.filter((s) => (s as { draw?: unknown }).draw && s.ranked).length;
  // Ranked systems per group on the merged board, independent of the current preset.
  const groupCounts = { open: published.systems.filter((s) => s.ranked && !isApi(s)).length, api: published.systems.filter((s) => s.ranked && isApi(s)).length };
  const updated = [...artifact.systems.map((s) => (s as { last_measured_on?: string }).last_measured_on ?? ''), JEV_BOARD_REVISIONS[0].date].sort().at(-1);
  // Florian 10 Oct 2026: one board, a filter on top, one line of text per idea; details live under "How it works".
  if (live) return <>
    <header className="bh-page-head" data-bh-jev16-release-header data-bh-jev16-live="true" data-bh-jev-board-scope={scope}>
      <div className="bh-eyebrow flex flex-nowrap items-center" data-bh-jev-frozen-version>{(board as { method?: unknown }).method ? <>JevBench · {jevMethodLabel(published)} · updated {updated}</> : <>JevBench · board {JEV_BOARD_REVISIONS[0].version} · updated {updated}</>}</div>
      <h1 className="mt-1 text-3xl font-bold tracking-tight">{scope === 'api' ? 'JevBench — hosted decision API benchmark' : scope === 'all' ? 'JevBench — all decision models' : 'JevBench — decision model benchmark & leaderboard'}</h1>
      <p className="mt-2 max-w-3xl text-lg" data-bh-jev-own>A <b>benchmark for AI decision models</b>: state and rubric in, typed answer out. We compare accuracy, calibration, latency and cost, independently of TypeSafe AI.</p>
      <p className="bh-muted mt-3 max-w-4xl text-xs leading-relaxed" data-bh-jev-meta>
        {scope === 'open' ? `${groupCounts.open} ranked open-weights systems · Jev 1.13.0 and Jev 1.14.0 shown as references` : scope === 'api' ? `${groupCounts.api} ranked API offerings` : `${groupCounts.open + groupCounts.api} ranked systems`}
        {' '}· {artifact.v16.counts.selfhosted_input.toLocaleString('en-US')} decisions each{a4Count > 0 && scope !== 'open' && ` (600 for ${a4Count} equated API re-runs)`}
        {cohortRows > 0 && <> · {cohortRows} newer ranked rows tagged with their draw</>}{carryCount > 0 && <> · {carryCount} older rows dated separately</>} ·
        {' '}<a className="text-accent underline" href="#jev16-method" data-bh-jev-how-it-works>How it works</a> ·
        {' '}<a className="text-accent underline" href="#jev-release-history" data-bh-jev-release-history-link>Release history</a> ·
        {' '}<a className="text-accent underline" href="/jev-models/methodology">Methodology</a> ·
        {' '}<a className="text-accent underline" href="/jev-models/data">Data & JSON/CSV</a> ·
        {' '}<a className="text-accent underline" href={`/api/jevbench/${revision}`}>aggregate JSON</a> ·
        {' '}<a className="text-accent underline" href={sharePath} data-bh-jev-version-share>Share</a> ·
        {' '}<a className="text-accent underline" href="/decision-model-benchmarks">Other decision benchmarks</a> ·
        {' '}<a className="text-accent underline" href="/image-jev-bench" data-bh-image-jev-link>Explore ImageJevBench v0.3.0</a>
      </p>
    </header>
    <JevBenchV16Board artifact={artifact} sha256={sha256} categories={categories} categoriesSha256={categoriesSha256}
      carry={carry} carrySha256={carrySha256} scope={scope} apiKeys={apiKeys} apiListed={apiListed} live
      previousKeys={[...previous.artifact.systems, ...previous.artifact.not_measured].filter((row: { key: string }) => !isJevbenchV16ExcludedKey(row.key, revision)).map((row: { key: string }) => row.key)} />
    <JevReleaseHistory />
    {scope !== 'open' && <JevBenchApiAddendumCoverage entries={addenda.entries} />}
  </>;

  return <>
    <JevBenchReleaseVersionNav active={revision} />
    <header className="bh-page-head" data-bh-jev16-release-header data-bh-jev16-live={live ? 'true' : undefined} data-bh-jev-board-scope={scope}>
      <div className="bh-eyebrow flex flex-nowrap items-center" data-bh-jev-frozen-version>
        Official JevBench {revision}{scope !== 'all' && ` · board ${JEV_BOARD_REVISIONS[0].version}`}
      </div>
      <h1 className="mt-1 text-3xl font-bold tracking-tight">{scope === 'api' ? 'JevBench — hosted decision API benchmark'
        : live ? 'JevBench — decision model benchmark & leaderboard' : `JevBench ${revision} — Jev alternatives ranking`}</h1>
      <p className="mt-3 max-w-3xl text-lg" data-bh-jev-own>JevBench by Benchmark Heaven is a <b>benchmark for AI decision models</b>, including Jev-compatible systems: state and a bounded rubric in, a typed answer out. Compare accuracy, probability calibration, latency and cost. Maintained independently of TypeSafe AI.</p>
      {scope === 'open' && <p className="mt-3 max-w-3xl text-base" data-bh-jev-scope-intro>This main board ranks <b>open-weights</b> decision models from published weights that we ran ourselves. The only API models kept on this board are two unranked reference rows from TypeSafe: <b>Jev 1.13.0</b>, the reference that defines the Jev-class caps, and <b>Jev 1.14.0</b>, TypeSafe&apos;s current version, shown for comparison (it is ranked on the API leaderboard).</p>}
      {/* v1.7.1 (Florian 6 Oct 2026): one expandable sentence on why the boards are split, with the link and the toggle. */}
      {scope === 'open' && <div className="mt-2 max-w-3xl text-base" data-bh-jev-split-why>
        <p><b>Why open weights and API offerings are separate:</b> open-weights models compare on equal hardware terms, so hosted APIs (Jev, wity, Sage, Fastino, …) have their own <a className="text-accent font-semibold underline" href="/jev-models/api" data-bh-jev-api-board-link>JevBench API leaderboard</a>, and “Show API offerings” below mixes them back in.</p>
        <details className="mt-1" data-bh-jev-split-why-more><summary className="cursor-pointer text-sm text-accent">Read why</summary>
        <ul className="bh-muted mt-2 list-disc space-y-1 pl-5 text-sm">
          <li><b>Fair cost and speed.</b> We run every open-weights model on hardware we rent and operate, so cost and latency compare on the same terms. The GPU cost calculator below prices your own setup: own hardware, on-demand or long-term rental.</li>
          <li><b>API prices can change.</b> An API price is the vendor&apos;s decision. It can be subsidised (for example on top-end GPUs) and raised later, and readers cannot reproduce it.</li>
          <li><b>Different fairness needs.</b> A hosted endpoint chooses its own hardware and sees the benchmark inputs, so API offerings are compared with each other on their own board.</li>
          <li><b>Open-source focus.</b> JevBench exists to make open decision models comparable and reproducible. The API board stays one click away, and every score and the method are identical on both boards.</li>
        </ul>
      </details></div>}
      {scope === 'api' && <p className="mt-3 max-w-3xl text-base" data-bh-jev-scope-intro>This board ranks <b>hosted API offerings</b>: decision APIs and models we reached through an endpoint we do not run. The <b>JevBench Composite Score</b> is the headline here: an API has one public price and one endpoint speed, so all four axes compare directly (on open weights both depend on your hardware, so Capability leads there). Open-weights models are ranked on the <a className="text-accent font-semibold underline" href="/jev-models" data-bh-jev-open-board-link>main JevBench board</a>; every score is identical on both boards.</p>}
      <p className="bh-muted mt-3 max-w-3xl text-xs leading-relaxed" data-bh-jev-meta>
        Release {revision} · {artifact.v16.counts.selfhosted_input.toLocaleString('en-US')} decisions per self-hosted system and {apiItems} per hosted API{a4Count > 0 && ` (600 for the ${a4Count} API rows re-run on A4 ∪ P on 6 Oct 2026, equated)`} ·
        {' '}{scope === 'open' ? `${rankedSelfHosted} ranked open-weights systems` : scope === 'api' ? `${rankedApi} ranked API offerings` : `${artifact.n_ranked} ranked systems`} · {carryCount} systems retain a separately dated v1.5.x score · only system-level aggregates are published ·
        {' '}<a className="text-accent underline" href={`/api/jevbench/${revision}`}>aggregate results JSON</a> · SHA-256 <code className="break-all">{sha256}</code>
      </p>
      <p className="mt-3 max-w-3xl text-sm" data-bh-jev-version-share-row>
        <a className="text-accent underline" href={sharePath} data-bh-jev-version-share>Share this {scope === 'api' ? 'board' : 'version'}</a>
        {!live && scope !== 'api' && <span className="bh-muted"> · <a className="text-accent underline" href="/jev-models" data-bh-jev-live-link>View live board</a></span>}
        {scope === 'all' && <span className="bh-muted"> · <a className="text-accent underline" href="/jev-models/api">API leaderboard</a></span>}
        <span className="bh-muted"> · Previous release: <a className="text-accent underline" href={previousHref}>JevBench {previousRelease}</a></span>
      </p>
      <nav className="mt-3 flex flex-wrap gap-3 text-sm" aria-label="JevBench methodology and data"><a className="text-accent underline" href="/jev-models/methodology">Methodology</a><a className="text-accent underline" href="/jev-models/data">Data card & JSON/CSV</a><a className="text-accent underline" href="/decision-model-benchmarks">Compare decision model benchmarks</a></nav>
      <p className="mt-3 max-w-3xl text-sm" data-bh-image-jev-link-row>Making decisions from images? <a className="text-accent font-semibold underline" href="/image-jev-bench" data-bh-image-jev-link>Explore ImageJevBench v0.3.0 and compare its systems</a>.</p>
    </header>
    <JevBenchV16Board artifact={artifact} sha256={sha256} categories={categories} categoriesSha256={categoriesSha256}
      carry={carry} carrySha256={carrySha256} scope={scope} apiKeys={apiKeys} apiListed={apiListed}
      previousKeys={[...previous.artifact.systems, ...previous.artifact.not_measured].filter((row: { key: string }) => !isJevbenchV16ExcludedKey(row.key, revision)).map((row: { key: string }) => row.key)} />
    <JevBenchApiAddendumCoverage entries={addenda.entries} />
  </>;
}
